function updateInventoryUI(){document.querySelectorAll('#inventorySlots .slot').forEach((el,i)=>{const item=equipment[i];el.textContent=item?(itemCatalog[item]?.icon||'◆'):'＋';el.title=item?itemCatalog[item].name:'Vide';el.classList.toggle('active',i===selectedSlot);el.classList.toggle('filled',!!item)});const active=equipment[selectedSlot];const n=document.querySelector('.weapon b');if(n)n.textContent=active?itemCatalog[active].name:'Aucun équipement';}
function addItem(type){const i=equipment.findIndex(x=>!x);if(i<0){toast('Inventaire plein — G pour jeter');return false}equipment[i]=type;inventory++;selectedSlot=i;updateInventoryUI();return true}
function dropSelected(){const type=equipment[selectedSlot];if(!type){toast('Emplacement vide');return}loot.push({pos:offset(player,0,-22),type});equipment[selectedSlot]=null;inventory=Math.max(0,inventory-1);updateInventoryUI();render();toast(itemCatalog[type].name+' jeté')}
function useSelected(){const type=equipment[selectedSlot];if(type==='bandage'||type==='medkit'){health=Math.min(100,health+(type==='medkit'?45:20));equipment[selectedSlot]=null;inventory=Math.max(0,inventory-1);updateHealth();updateInventoryUI();toast('Soin utilisé')}else if(type==='water'||type==='food'||type==='battery'){equipment[selectedSlot]=null;inventory=Math.max(0,inventory-1);updateInventoryUI();toast(itemCatalog[type].name+' consommé')}}
function drawWaypoint(){if(!waypoint)return;const a=project(player),b=project(waypoint);ctx.save();ctx.strokeStyle='#52d9ff';ctx.lineWidth=2;ctx.setLineDash([7,6]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#52d9ff';ctx.beginPath();ctx.arc(b.x,b.y,7,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawMiniMap(){const c=document.getElementById('miniMapCanvas');if(!c)return;const g=c.getContext('2d'),cx=90,cy=90,range=420;g.clearRect(0,0,180,180);g.fillStyle='#102936';g.fillRect(0,0,180,180);function dot(pos,color,r){const q=local(pos),x=cx+q.lng/range*85,y=cy-q.north/range*85;if(x<2||x>178||y<2||y>178)return;g.fillStyle=color;g.beginPath();g.arc(x,y,r,0,Math.PI*2);g.fill()}bots.forEach(b=>dot(b.pos,'#f16d7b',3));loot.forEach(o=>dot(o.pos,'#ffd15c',2));if(waypoint){dot(waypoint,'#54dfff',4);const q=local(waypoint);g.strokeStyle='#54dfff';g.setLineDash([4,3]);g.beginPath();g.moveTo(cx,cy);g.lineTo(cx+q.lng/range*85,cy-q.north/range*85);g.stroke();g.setLineDash([])}g.fillStyle='#48f0c3';g.beginPath();g.arc(cx,cy,4,0,Math.PI*2);g.fill();const label=document.getElementById('routeDistance');if(label)label.textContent=waypoint?Math.round(distance(player,waypoint))+' m restants':'Maj + clic sur la carte pour placer un repère'}
function polygonAreaMeters(coords){let area=0;for(let i=0,j=coords.length-1;i<coords.length;j=i++){const a=coords[i],b=coords[j];area+=(a[1]*111320)*(b[0]*111320)-(b[1]*111320)*(a[0]*111320)}return Math.abs(area/2)}
function segmentDistance(p,a,b){const q=local(p),aa=local(L.latLng(a[0],a[1])),bb=local(L.latLng(b[0],b[1]));const vx=bb.lng-aa.lng,vy=bb.north-aa.north,wx=q.lng-aa.lng,wy=q.north-aa.north,t=Math.max(0,Math.min(1,(wx*vx+wy*vy)/(vx*vx+vy*vy+1e-9)));return Math.hypot(q.lng-(aa.lng+t*vx),q.north-(aa.north+t*vy))}
function nearestBuilding(){let best=-1,dist=Infinity;buildingPolys.forEach((poly,i)=>{let d=pointInPoly(player,poly)?0:Infinity;for(let j=0;j<poly.length-1;j++)d=Math.min(d,segmentDistance(player,poly[j],poly[j+1]));if(d<dist){dist=d;best=i}});return{index:best,distance:dist}}
function toggleInterior(){if(interior){player=interior.returnPos;interior=null;toast('Sortie du bâtiment');render();return}const n=nearestBuilding();if(n.index>=0&&n.distance<42){interior={index:n.index,roomX:0,roomY:0,floor:0,doors:{},itemCollected:false,returnPos:player,variant:buildingMeta[n.index]?.variant??(n.index%5)};const safe=nearestInteriorWalkable(.5,.5,buildingMeta[n.index]||{});interior.roomX=(safe.x-.5)/.4;interior.roomY=(safe.y-.5)/.4;toast('Entrée — F pour ressortir');render()}else toast('Approche la façade d’un bâtiment pour entrer')}
function makeZone(){if(zoneCircle)map.removeLayer(zoneCircle);zoneCircle=L.circle(zoneCenter,{radius:zoneRadius,color:'#35e5b4',weight:2,fillColor:'#35e5b4',fillOpacity:.04,dashArray:'8 8'}).addTo(map)}
