async function loadElevation(){if(map.getZoom()<14)return;const b=map.getBounds(),center=map.getCenter(),cellKey=Math.floor(center.lat/.006)+':'+Math.floor(center.lng/.006)+':'+map.getZoom();if(cellKey===elevationCellKey||elevationLoading)return;elevationLoading=true;const rows=5,cols=5,south=b.getSouth(),north=b.getNorth(),west=b.getWest(),east=b.getEast(),lats=[],lons=[];for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){lats.push((north-(north-south)*y/(rows-1)).toFixed(5));lons.push((west+(east-west)*x/(cols-1)).toFixed(5))}try{const values=[];for(let start=0;start<lats.length;start+=100){const la=lats.slice(start,start+100),lo=lons.slice(start,start+100),url='https://api.open-meteo.com/v1/elevation?latitude='+la.join(',')+'&longitude='+lo.join(',');const res=await fetch(url,{signal:AbortSignal.timeout(7000)});if(!res.ok)throw Error('Elevation API HTTP '+res.status);const data=await res.json();values.push(...data.elevation)}if(values.length===rows*cols&&values.every(Number.isFinite)){elevationGrid={rows,cols,south,north,west,east,values};elevationCellKey=cellKey;render();updateTerrainReadout()}}catch(e){console.warn('Elevation data unavailable',e)}finally{elevationLoading=false}}
function drawElevation(){const g=elevationGrid;if(!g)return;ctx.save();for(let y=0;y<g.rows-1;y++)for(let x=0;x<g.cols-1;x++){const ids=[y*g.cols+x,y*g.cols+x+1,(y+1)*g.cols+x+1,(y+1)*g.cols+x],v=ids.map(i=>g.values[i]),avg=v.reduce((a,b)=>a+b,0)/4,range=Math.max(...v)-Math.min(...v),pts=[[y,x],[y,x+1],[y+1,x+1],[y+1,x]].map(([yy,xx])=>project(L.latLng(g.north-(g.north-g.south)*yy/(g.rows-1),g.west+(g.east-g.west)*xx/(g.cols-1))));const shade=Math.max(0,Math.min(1,range/45));ctx.beginPath();ctx.moveTo(pts[0].x,pts[0].y);pts.slice(1).forEach(p=>ctx.lineTo(p.x,p.y));ctx.closePath();ctx.fillStyle=avg>500?'rgba(195,157,105,'+(0.025+shade*.08)+')':'rgba(47,111,99,'+(0.018+shade*.065)+')';ctx.fill();if(range>24){ctx.strokeStyle='rgba(225,237,215,.13)';ctx.lineWidth=1;ctx.stroke()}}ctx.restore()}
function updateTerrainReadout(){const el=document.getElementById('terrainReadout');if(!el)return;const h=elevationAt(player);if(h===null){el.textContent='RELIEF : CHARGEMENT…';return}const ahead=offset(player,0,12),ha=elevationAt(ahead),grade=ha===null?0:(ha-h)/12;el.textContent='ALT. '+Math.round(h)+' m • '+(grade>.08?'PENTE ↑':grade<-.08?'PENTE ↓':'PLAT')}
document.getElementById('worldLoadStatus')?.querySelector('[data-world-retry]')?.addEventListener('click',()=>loadWorld(true));
function setWorldLoadState(message,loading=false,failed=false){const panel=document.getElementById('worldLoadStatus');if(!panel)return;const label=panel.querySelector('[data-world-status]');const retry=panel.querySelector('[data-world-retry]');label.textContent=message;panel.classList.toggle('is-loading',loading);panel.classList.toggle('is-error',failed);panel.hidden=!loading&&!failed&&!message.includes('Carte prête');retry.hidden=!failed;}
