document.getElementById('restart').onclick=()=>location.reload();document.getElementById('locate').onclick=()=>document.getElementById('cityModal').classList.add('open');document.getElementById('closeModal').onclick=()=>document.getElementById('cityModal').classList.remove('open');document.getElementById('searchCity').onclick=searchCity;document.getElementById('cityInput').addEventListener('keydown',e=>{if(e.key==='Enter')searchCity()});
let citySearchInFlight=false;async function searchCity(){const q=document.getElementById('cityInput').value.trim();if(!q||citySearchInFlight)return;const box=document.getElementById('cityResults'),button=document.getElementById('searchCity'),en=document.documentElement.lang==='en';citySearchInFlight=true;button.disabled=true;button.setAttribute('aria-busy','true');box.textContent=en?'Searching…':'Recherche…';try{let results=[],lastError=null;const providers=[{url:'https://nominatim.openstreetmap.org/search?format=json&limit=5&q='+encodeURIComponent(q),parse:d=>d.map(p=>({lat:p.lat,lon:p.lon,name:p.display_name}))},{url:'https://photon.komoot.io/api/?limit=5&q='+encodeURIComponent(q),parse:d=>(d.features||[]).map(f=>({lat:f.geometry?.coordinates?.[1],lon:f.geometry?.coordinates?.[0],name:[f.properties?.name,f.properties?.city,f.properties?.state,f.properties?.country].filter(Boolean).join(', ')}))}];for(const provider of providers){try{const resp=await fetch(provider.url,{signal:AbortSignal.timeout(8000)});if(!resp.ok)throw Error('Geocoder HTTP '+resp.status);const data=provider.parse(await resp.json());if(data.length){results=data;break}}catch(error){lastError=error;console.warn('Geocoder unavailable',error)}}box.replaceChildren();if(!results.length){box.textContent=lastError?(en?'Location search unavailable. Check your connection and try again.':'Recherche indisponible. Vérifie ta connexion puis réessaie.'):(en?'No results found':'Aucun résultat');return}results.forEach(p=>{const lat=Number(p.lat),lon=Number(p.lon);if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)return;const btn=document.createElement('button');btn.className='city-result';btn.textContent=p.name||q;btn.onclick=()=>startCity(lat,lon,p.name||q);box.appendChild(btn)});if(!box.childElementCount)box.textContent=en?'No valid location found':'Aucun lieu valide trouvé'}finally{citySearchInFlight=false;button.disabled=false;button.removeAttribute('aria-busy')}}
function startCity(lat,lon,name){document.body.classList.remove('home-active');document.body.classList.add('game-active');choosingStartLocation=false;interior=null;player=L.latLng(lat,lon);unlockGameplayCamera();setMapStyle('cyber');elevationGrid=null;elevationCellKey='';zoneCenter=player;map.setView(player,19);lockGameplayCamera();bots=[];loot=[];equipment=Array(6).fill(null);selectedSlot=0;waypoint=null;spawn();zoneRadius=2500;countdown=120;health=100;inventory=0;eliminations=0;document.getElementById('kills').textContent='0';document.querySelectorAll('.inventory .slot').forEach(s=>{s.textContent='＋';s.classList.remove('active','filled')});updateInventoryUI();updateHealth();makeZone();buildingPolys=[];buildingMeta=[];roadLines=[];obstacles=[];waterPolys=[];waterLines=[];bridgeLines=[];tunnelLines=[];railLines=[];sidewalkLines=[];parkingPolys=[];treePoints=[];crossingPoints=[];forestPolys=[];greenPolys=[];cliffLines=[];if(worldFeatureLayer){map.removeLayer(worldFeatureLayer);worldFeatureLayer=null}worldLoaded=false;lastQuery='';document.getElementById('cityModal').classList.remove('open');document.getElementById('gameOver').classList.remove('show');gameEnded=false;render();scheduleGameLoop();toast('Nouvelle zone: '+name+' — carte en chargement');requestAnimationFrame(()=>{if(document.body.classList.contains('game-active')){loadWorld();loadElevation()}})}
render();toast('Monde isométrique prêt — recherche des données réelles');

// JUJU WORLD: enter the playable world only after pressing PLAY.
const homeNotice=document.getElementById('homeNotice');let noticeTimer;
function showHomeNotice(message){homeNotice.textContent=message;homeNotice.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>homeNotice.classList.remove('show'),2400)}
let choosingStartLocation=false;
document.getElementById('playBtn').addEventListener('click',()=>{const modal=document.getElementById('cityModal');modal.classList.add('open');document.getElementById('cityInput').focus()});
let earthGlobeInstance=null,earthSelected=null,earthGlobeLoading=false;
function openEarthPicker(){const modal=document.getElementById('earthPicker');modal.classList.add('open');document.getElementById('cityModal').classList.remove('open');if(earthGlobeInstance){earthGlobeInstance.width(document.getElementById('earthGlobe').clientWidth);earthGlobeInstance.height(document.getElementById('earthGlobe').clientHeight);return}if(earthGlobeLoading)return;earthGlobeLoading=true;const script=document.createElement('script');script.src='https://unpkg.com/globe.gl';script.onload=()=>{try{const host=document.getElementById('earthGlobe');earthGlobeInstance=Globe()(host).globeImageUrl('https://unpkg.com/three-globe/example/img/earth-blue-marble.jpg').backgroundColor('#020711').showAtmosphere(true).atmosphereColor('#39bff2').atmosphereAltitude(.18).width(host.clientWidth).height(host.clientHeight).onGlobeClick(({lat,lng})=>selectEarthPoint(lat,lng));earthGlobeInstance.pointOfView({lat:24,lng:8,altitude:2.1},0);earthGlobeInstance.controls().autoRotate=false;earthGlobeInstance.controls().enableDamping=true;earthGlobeInstance.controls().dampingFactor=.08;document.getElementById('earthFallback').hidden=true;}catch(error){console.error('Earth globe initialization failed',error);showEarthFallback()}};script.onerror=showEarthFallback;document.head.appendChild(script);function showEarthFallback(){earthGlobeLoading=false;document.getElementById('earthFallback').hidden=false;document.getElementById('earthFallback').textContent='Globe 3D indisponible. Tu peux revenir à la carte 2D pour choisir ton lieu.';const fallback=document.createElement('button');fallback.textContent='CHOISIR SUR LA CARTE 2D';fallback.onclick=()=>{document.getElementById('earthPicker').classList.remove('open');choosingStartLocation=true;document.body.classList.remove('home-active');document.body.classList.add('game-active');map.setView([20,0],2);toast('Clique sur la carte pour choisir ton point de départ')};document.getElementById('earthFallback').appendChild(fallback)}}
function selectEarthPoint(lat,lng){earthSelected={lat,lng};if(earthGlobeInstance)earthGlobeInstance.pointsData([{lat,lng,size:.22,color:'#ff4bd8'}]).pointAltitude(.025).pointRadius(.35).pointColor('color');document.getElementById('earthCoordinates').textContent=lat.toFixed(4)+'° / '+lng.toFixed(4)+'°';document.getElementById('confirmEarthLocation').disabled=false;}
document.getElementById('pickMapLocation').addEventListener('click',openEarthPicker);
document.getElementById('closeEarthPicker').addEventListener('click',()=>document.getElementById('earthPicker').classList.remove('open'));
document.getElementById('confirmEarthLocation').addEventListener('click',()=>{if(!earthSelected)return;const p=earthSelected;document.getElementById('earthPicker').classList.remove('open');startCity(p.lat,p.lng,'Position choisie sur le globe')});
map.on('click',e=>{if(!choosingStartLocation)return;choosingStartLocation=false;startCity(e.latlng.lat,e.latlng.lng,'Position choisie sur la carte')});
window.addEventListener('resize',()=>{if(earthGlobeInstance&&document.getElementById('earthPicker').classList.contains('open')){const host=document.getElementById('earthGlobe');earthGlobeInstance.width(host.clientWidth).height(host.clientHeight)}});
function saveLocalGame(){
 const snapshot={version:1,savedAt:new Date().toISOString(),player:{lat:player.lat,lng:player.lng},zoneCenter:{lat:zoneCenter.lat,lng:zoneCenter.lng},bots:bots.map(b=>({lat:b.pos.lat,lng:b.pos.lng})),loot:loot.map(o=>({lat:o.pos.lat,lng:o.pos.lng,type:o.type||'bandage'})),health,inventory,eliminations,zoneRadius,countdown,equipment,selectedSlot,waypoint:waypoint?{lat:waypoint.lat,lng:waypoint.lng}:null};
 try{localStorage.setItem('juju-world-save-v1',JSON.stringify(snapshot));showHomeNotice('Partie sauvegardée sur cet appareil.')}catch(e){showHomeNotice('Sauvegarde impossible : espace local indisponible.')}
}
function loadLocalGame(){
 try{const raw=localStorage.getItem('juju-world-save-v1');if(!raw){showHomeNotice('Aucune sauvegarde locale trouvée.');return}const s=JSON.parse(raw);if(s.version!==1||!s.player||!Number.isFinite(s.player.lat)||!Number.isFinite(s.player.lng))throw Error('Invalid save');
 interior=null;player=L.latLng(s.player.lat,s.player.lng);zoneCenter=L.latLng(s.zoneCenter?.lat??s.player.lat,s.zoneCenter?.lng??s.player.lng);bots=(s.bots||[]).map(p=>({pos:L.latLng(p.lat,p.lng)}));loot=(Array.isArray(s.loot)?s.loot:[]).filter(p=>p&&Number.isFinite(p.lat)&&Number.isFinite(p.lng)).map(p=>({pos:L.latLng(p.lat,p.lng),type:Object.prototype.hasOwnProperty.call(itemCatalog,p.type)?p.type:'bandage'}));health=Math.max(0,Math.min(100,s.health??100));inventory=Math.max(0,s.inventory||0);equipment=Array.isArray(s.equipment)?s.equipment.slice(0,6).map(item=>Object.prototype.hasOwnProperty.call(itemCatalog,item)?item:null):Array(6).fill(null);while(equipment.length<6)equipment.push(null);selectedSlot=Math.max(0,Math.min(5,s.selectedSlot||0));waypoint=s.waypoint?L.latLng(s.waypoint.lat,s.waypoint.lng):null;eliminations=s.eliminations||0;updateInventoryUI();zoneRadius=s.zoneRadius||2500;countdown=s.countdown||120;map.setView(player,17);document.body.classList.remove('home-active');document.body.classList.add('game-active');document.getElementById('kills').textContent=eliminations;document.getElementById('players').textContent=bots.length+1;updateHealth();makeZone();worldLoaded=false;lastQuery='';requestAnimationFrame(()=>{if(document.body.classList.contains('game-active')){loadWorld();loadElevation()}});gameEnded=false;render();scheduleGameLoop();showHomeNotice('Sauvegarde chargée.');
 }catch(e){showHomeNotice('Sauvegarde illisible ou incompatible.')}
}
document.getElementById('savesBtn').addEventListener('click',loadLocalGame);
const settingsModal=document.getElementById('settingsModal'),layoutSelect=document.getElementById('movementLayout');
layoutSelect.value=movementLayout;
document.getElementById('settingsBtn').addEventListener('click',()=>settingsModal.classList.add('open'));
document.getElementById('closeSettings').addEventListener('click',()=>settingsModal.classList.remove('open'));
document.getElementById('saveSettings').addEventListener('click',()=>{movementLayout=layoutSelect.value;const saved=writeLocalStorage('juju-movement-layout',movementLayout);settingsModal.classList.remove('open');showHomeNotice(saved?'Paramètres enregistrés.':'Stockage indisponible : paramètres non enregistrés.')});
document.getElementById('saveGameBtn').addEventListener('click',saveLocalGame);
document.getElementById('autoSaveToggle').checked=readLocalStorage('juju-autosave')!=='false';
document.getElementById('autoSaveToggle').addEventListener('change',e=>{if(!writeLocalStorage('juju-autosave',String(e.target.checked)))showHomeNotice('Stockage indisponible : préférence non enregistrée.')});
window.addEventListener('beforeunload',()=>{if(readLocalStorage('juju-autosave')!=='false'&&document.body.classList.contains('game-active')){const snapshot={version:1,savedAt:new Date().toISOString(),player:{lat:player.lat,lng:player.lng},zoneCenter:{lat:zoneCenter.lat,lng:zoneCenter.lng},bots:bots.map(b=>({lat:b.pos.lat,lng:b.pos.lng})),loot:loot.map(o=>({lat:o.pos.lat,lng:o.pos.lng,type:o.type||'bandage'})),health,inventory,eliminations,zoneRadius,countdown,equipment,selectedSlot,waypoint:waypoint?{lat:waypoint.lat,lng:waypoint.lng}:null};try{localStorage.setItem('juju-world-save-v1',JSON.stringify(snapshot))}catch{}}});

